package ml.pkom.uncraftingtable.client;

import java.io.File;
import me.shedaniel.clothconfig2.api.AbstractConfigListEntry;
import me.shedaniel.clothconfig2.api.ConfigBuilder;
import me.shedaniel.clothconfig2.api.ConfigCategory;
import me.shedaniel.clothconfig2.api.ConfigEntryBuilder;
import ml.pkom.easyapi.FileControl;
import ml.pkom.mcpitanlibarch.api.util.TextUtil;
import ml.pkom.uncraftingtable.Config;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;

public class ClothConfig {
    public static Screen create(Screen screen) {
        ConfigBuilder builder = ConfigBuilder.create().setParentScreen(screen).setTitle((Component)TextUtil.translatable((String)"title.uncraftingtable76.config")).setSavingRunnable(() -> {
            if (!FileControl.fileExists((File)Config.getConfigDir())) {
                Config.getConfigDir().mkdirs();
            }
            Config.config.save(Config.getConfigFile());
        });
        ConfigEntryBuilder entryBuilder = builder.entryBuilder();
        ConfigCategory general = builder.getOrCreateCategory((Component)TextUtil.translatable((String)"category.uncraftingtable76.general"));
        general.addEntry((AbstractConfigListEntry)entryBuilder.startIntField((Component)TextUtil.translatable((String)"option.uncraftingtable76.consume_xp"), Config.config.getInt("consume_xp")).setDefaultValue(0).setSaveConsumer(newValue -> Config.config.setInt("consume_xp", newValue.intValue())).build());
        general.addEntry((AbstractConfigListEntry)entryBuilder.startBooleanToggle((Component)TextUtil.translatable((String)"option.uncraftingtable76.uncraft_damaged_item"), Config.config.getBoolean("uncraft_damaged_item")).setDefaultValue(true).setSaveConsumer(newValue -> Config.config.setBoolean("uncraft_damaged_item", newValue.booleanValue())).build());
        general.addEntry((AbstractConfigListEntry)entryBuilder.startBooleanToggle((Component)TextUtil.translatable((String)"option.uncraftingtable76.restore_enchantment_book"), Config.config.getBoolean("restore_enchantment_book")).setDefaultValue(true).setSaveConsumer(newValue -> Config.config.setBoolean("restore_enchantment_book", newValue.booleanValue())).build());
        general.addEntry((AbstractConfigListEntry)entryBuilder.startBooleanToggle((Component)TextUtil.translatable((String)"option.uncraftingtable76.disable_uncrafting_uu_matter"), Config.config.getBoolean("disable_uncrafting_uu_matter")).setDefaultValue(true).setSaveConsumer(newValue -> Config.config.setBoolean("disable_uncrafting_uu_matter", newValue.booleanValue())).build());
        return builder.build();
    }
}

