    }
    if (path.contains("nethersteel")) {
        return ModList.get().isLoaded("createbigcannons");
    }
    if (path.contains("compressed_iron")) {
        return ModList.get().isLoaded("pneumaticcraft");
    }
    if (path.contains("electrum")) {
        return ModList.get().isLoaded("createaddition");
    }
    return true;
}

